// Helper lemma: when inserting (r, t) and filtering by val.0 == r, the length increases by 1
broadcast proof fn lemma_filter_insert_r<T>(sg: Multiset<(int, T)>, r: int, t: T)
    ensures
        Self::filter_r(sg.insert((r, t)), r).len() == Self::filter_r(sg, r).len() + 1,
{
    // Let's prove this by extensionality
    // We need to show that the count of each element in the filtered multiset
    // either stays the same or increases by 1 (for the element (r, t) if it gets added)

    // For any element v:
    // sg.insert((r, t)).filter(f).count(v) =
    //   if f(v) then sg.insert((r, t)).count(v) else 0
    // = if f(v) then (if v == (r, t) then sg.count(v) + 1 else sg.count(v)) else 0
    //
    // sg.filter(f).count(v) = if f(v) then sg.count(v) else 0
    //
    // So if f(v):
    //   sg.insert((r, t)).filter(f).count(v) =
    //     if v == (r, t) then sg.count(v) + 1 else sg.count(v)
    //   = sg.filter(f).count(v) + (if v == (r, t) then 1 else 0)
    //
    // If not f(v):
    //   sg.insert((r, t)).filter(f).count(v) = 0 = sg.filter(f).count(v)
    //
    // Now for length:
    // len = sum of counts over all elements
    // The only element whose count changes is (r, t) when f(r, t)
    // Since f = |val| val.0 == r, we have f(r, t) iff r == r, which is always true
    // So (r, t)'s count increases by 1, and all others stay the same
    // Therefore, the sum (length) increases by 1

    let f = |val: (int, T)| val.0 == r;

    // Prove by extensionality that the counts differ by 1 for (r, t) and 0 for others
    assert forall|v: (int, T)| 
        #[trigger] sg.insert((r, t)).filter(f).count(v) ==
            sg.filter(f).count(v) + (if v == (r, t) && f(v) { 1 } else { 0 })
    by {
        let sg_ins = sg.insert((r, t));
        let flt_sg = sg.filter(f);
        let flt_sg_ins = sg_ins.filter(f);

        if f(v) {
            // v is in the filter
            if v == (r, t) {
                // It's the element we inserted
                // sg_ins.count(v) = sg.count(v) + 1
                // flt_sg_ins.count(v) = sg_ins.count(v) = sg.count(v) + 1
                // flt_sg.count(v) = sg.count(v)
