#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    assert forall|rr: int| 0 <= rr < post.rc_width implies
        post.ref_counts.index(rr) ==
            post.shared_pending.count(rr) as int +
                Self::filter_r(post.shared_guard, rr).len() as int
    by {
        assert(post.ref_counts == pre.ref_counts);
        assert(post.shared_pending == pre.shared_pending.remove(r));
        assert(post.shared_guard == pre.shared_guard.insert((r, pre.storage->0)));

        assert(pre.shared_counts_agree());
        assert(pre.ref_counts.index(rr) ==
            pre.shared_pending.count(rr) as int +
                Self::filter_r(pre.shared_guard, rr).len() as int);

        if rr == r {
            // For rr == r:
            // post.shared_pending.count(r) = pre.shared_pending.count(r) - 1
            // Self::filter_r(post.shared_guard, r).len() = Self::filter_r(pre.shared_guard, r).len() + 1
            // Sum: pre.shared_pending.count(r) - 1 + Self::filter_r(pre.shared_guard, r).len() + 1
            //    = pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len
            //    = pre.ref_counts.index(r)  (by pre.shared_counts_agree)
            //    = post.ref_counts.index(r)
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
            // The insert adds 1 to the filter length because (r, t).0 == r
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);
        } else {
            // For rr != r:
            // post.shared_pending.count(rr) = pre.shared_pending.count(rr)
            // Self::filter_r(post.shared_guard, rr).len() = Self::filter_r(pre.shared_guard, rr).len()
            // Both sides unchanged, so equality preserved
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());
        }
    }
}

