broadcast proof fn lemma_filter_insert_r(sg: Multiset<(int, T)>, r: int, t: T)
    ensures
        Self::filter_r(sg.insert((r, t)), r).len() == Self::filter_r(sg, r).len() + 1,
{
    // Let f(v) = v.0 == r
    // We want to show: filter(sg.insert((r,t)), f).len() = filter(sg, f).len() + 1
    //
    // By properties of len and count:
    // len(m) = sum of count(m, v) over all v
    //
    // For any v:
    // count(filter(sg.insert((r,t)), f), v) =
    //   if f(v) then count(sg.insert((r,t)), v) else 0
    // = if f(v) then (if v == (r,t) then count(sg, v) + 1 else count(sg, v)) else 0
    //
    // count(filter(sg, f), v) = if f(v) then count(sg, v) else 0
    //
    // Case 1: f(v) = true (i.e., v.0 == r)
    //   If v == (r,t):
    //     count(filter(sg.insert((r,t)), f), v) = count(sg, v) + 1
    //     count(filter(sg, f), v) = count(sg, v)
    //     Difference: 1
    //   If v != (r,t):
    //     count(filter(sg.insert((r,t)), f), v) = count(sg, v)
    //     count(filter(sg, f), v) = count(sg, v)
    //     Difference: 0
    //
    // Case 2: f(v) = false
    //   Both counts are 0
    //
    // Summing over all v, the only element with non-zero difference is (r,t),
    // and the difference is 1. So the total difference in lengths is 1.

    let f = |val: (int, T)| val.0 == r;

    // Prove that the counts differ by 1 for (r,t) when f(r,t), and 0 otherwise
    assert forall|v: (int, T)|
        #[trigger] sg.insert((r, t)).filter(f).count(v) ==
            sg.filter(f).count(v) + (if v == (r, t) && f(v) { 1 } else { 0 })
    by {
        if f(v) {
            // v is in the filter
            if v == (r, t) {
                // It's the element we inserted
                // count(sg.insert((r,t)), v) = count(sg, v) + 1
                // filter keeps this count since f(v)
                assert(sg.insert((r, t)).count(v) == sg.count(v) + 1);
                assert(sg.insert((r, t)).filter(f).count(v) == sg.insert((r, t)).count(v));
                assert(sg.filter(f).count(v) == sg.count(v));
                assert(sg.insert((r, t)).filter(f).count(v) == sg.filter(f).count(v) + 1);
            } else {
                // It's a different element in the filter
                // count(sg.insert((r,t)), v) = count(sg, v)
                // filter keeps this count since f(v)
                assert(sg.insert((r, t)).count(v) == sg.count(v));
                assert(sg.insert((r, t)).filter(f).count(v) == sg.insert((r, t)).count(v));
                assert(sg.filter(f).count(v) == sg.count(v));
                assert(sg.insert((r, t)).filter(f).count(v) == sg.filter(f).count(v));
            }
        } else {
            // v is not in the filter
            // Both filtered counts are 0
            assert(sg.insert((r, t)).filter(f).count(v) == 0);
            assert(sg.filter(f).count(v) == 0);
        }
    }

    // Now relate this to lengths
    // The difference in lengths is the sum of differences in counts over all elements
    // The only element with non-zero difference is (r,t) when f(r,t)
    // Since f(r,t) = (r.0 == r) = true, the difference is 1
    assert(Self::filter_r(sg.insert((r, t)), r).len() ==
        Self::filter_r(sg, r).len() + 1);
}

