    ensures
        Self::filter_r(sg.insert((r, t)), r).len() == Self::filter_r(sg, r).len() + 1,
{
    // Let f(v) = v.0 == r
    // We want to show: filter(sg.insert((r,t)), f).len() = filter(sg, f).len() + 1
    //
    // For any v:
    // count(filter(sg.insert((r,t)), f), v) = if f(v) then count(sg.insert((r,t)), v) else 0
    // count(filter(sg, f), v) = if f(v) then count(sg, v) else 0
    //
    // Case 1: v == (r, t) and f(v) (which is true since r.0 == r)
    //   count(filter(sg.insert((r,t)), f), (r,t)) = count(sg, (r,t)) + 1
    //   count(filter(sg, f), (r,t)) = count(sg, (r,t))
    //   Difference: 1
    //
    // Case 2: v != (r, t) and f(v)
    //   count(filter(sg.insert((r,t)), f), v) = count(sg, v)
    //   count(filter(sg, f), v) = count(sg, v)
    //   Difference: 0
    //
    // Case 3: not f(v)
    //   Both are 0
    //
    // So the sum (length) increases by 1.

    let f = |val: (int, T)| val.0 == r;

    // Show count properties
    assert forall|v: (int, T)|
        f(v) && v == (r, t) implies
            sg.insert((r, t)).filter(f).count(v) ==
                sg.filter(f).count(v) + 1
    by {
        assert(sg.insert((r, t)).count(v) == sg.count(v) + 1) by {
            axiom_multiset_add(sg, Multiset::singleton((r, t)), v);
            axiom_multiset_singleton((r, t));
        }
        assert(sg.insert((r, t)).filter(f).count(v) == sg.insert((r, t)).count(v)) by {
            axiom_filter_count(sg.insert((r, t)), f, v);
        }
        assert(sg.filter(f).count(v) == sg.count(v)) by {
            axiom_filter_count(sg, f, v);
        }
    }

    assert forall|v: (int, T)|
        f(v) && v != (r, t) implies
            sg.insert((r, t)).filter(f).count(v) ==
                sg.filter(f).count(v)
    by {
        assert(sg.insert((r, t)).count(v) == sg.count(v)) by {
            axiom_multiset_add(sg, Multiset::singleton((r, t)), v);
            axiom_multiset_singleton_different((r, t), v);
        }
        assert(sg.insert((r, t)).filter(f).count(v) == sg.insert((r, t)).count(v)) by {
            axiom_filter_count(sg.insert((r, t)), f, v);
        }
        assert(sg.filter(f).count(v) == sg.count(v)) by {
            axiom_filter_count(sg, f, v);
        }
    }

    assert forall|v: (int, T)|
        !f(v) implies
            sg.insert((r, t)).filter(f).count(v) ==
                sg.filter(f).count(v)
    by {
        assert(sg.insert((r, t)).filter(f).count(v) == 0) by {
            axiom_filter_count(sg.insert((r, t)), f, v);
        }
        assert(sg.filter(f).count(v) == 0) by {
            axiom_filter_count(sg, f, v);
        }
    }

