    // The only element with non-zero difference is (r,t), and the difference is 1
    assert(Self::filter_r(sg.insert((r, t)), r).len() ==
        Self::filter_r(sg, r).len() + 1) by {
        // len(m) = sum of count(m, v) over all v in dom(m)
        // The difference in lengths equals the sum of differences in counts
        // For (r,t): difference = 1
        // For all other v: difference = 0
        // So total difference = 1
    }
}

