#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    assert forall|rr: int| 0 <= rr < post.rc_width implies
        post.ref_counts.index(rr) ==
            post.shared_pending.count(rr) as int +
                Self::filter_r(post.shared_guard, rr).len() as int
    by {
        assert(post.ref_counts == pre.ref_counts);
        assert(post.shared_pending == pre.shared_pending.remove(r));
        assert(post.shared_guard == pre.shared_guard.insert((r, pre.storage->0)));

        assert(pre.shared_counts_agree());
        assert(pre.ref_counts.index(rr) ==
            pre.shared_pending.count(rr) as int +
                Self::filter_r(pre.shared_guard, rr).len() as int);

        // Key insight: for filter_r with predicate val.0 == rr:
        // - When rr == r: filter length increases by 1 (because we add (r,t) where r.0 == r)
        // - When rr != r: filter length unchanged (because (r,t).0 == r != rr)
        // And shared_pending removes r, so for rr == r, count decreases by 1
        // The changes cancel out, preserving the invariant

        if rr == r {
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
            // Prove: filter_r(sg.insert((r,t)), r).len() = filter_r(sg, r).len() + 1
            // where filter_r(sg, r) = sg.filter(|val| val.0 == r)
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1) by {
                // f(v) = v.0 == r
                // len(filter(m, f)) = sum of m.count(v) for all v where f(v)
                // 
                // len(filter(sg.insert((r,t)), f))
                // = sum of (sg.insert((r,t)).count(v)) for all v where v.0 == r
                // = (sum of (sg.count(v)) for all v where v.0 == r and v != (r,t)) + sg.count((r,t)) + 1
                // = (sum of (sg.count(v)) for all v where v.0 == r) + 1
                // = len(filter(sg, f)) + 1

                let f = |val: (int, T)| val.0 == r;

                // For (r,t): f(r,t) = true, and sg.insert((r,t)).count((r,t)) = sg.count((r,t)) + 1
                assert(f((r, t)));
                assert(sg.insert((r, t)).count((r, t)) == sg.count((r, t)) + 1) by {
                    axiom_multiset_add(sg, Multiset::singleton((r, t)), (r, t));
                    axiom_multiset_singleton((r, t));
