            sg.insert((r, t)).count(v) == sg.count(v) + 1
    by {
        axiom_multiset_add(sg, Multiset::singleton((r, t)), v);
        axiom_multiset_singleton((r, t));
    }

    assert forall|v: (int, T)|
        f(v) && v != (r, t) implies
            sg.insert((r, t)).count(v) == sg.count(v)
    by {
        axiom_multiset_add(sg, Multiset::singleton((r, t)), v);
        axiom_multiset_singleton_different((r, t), v);
    }

    // Prove filter count properties
    assert forall|v: (int, T)|
        #[trigger] f(v) && v == (r, t) implies
            sg.insert((r, t)).filter(f).count(v) == sg.filter(f).count(v) + 1
    by {
        assert(sg.insert((r, t)).count(v) == sg.count(v) + 1);
        axiom_filter_count(sg.insert((r, t)), f, v);
        axiom_filter_count(sg, f, v);
    }

    assert forall|v: (int, T)|
        #[trigger] f(v) && v != (r, t) implies
            sg.insert((r, t)).filter(f).count(v) == sg.filter(f).count(v)
    by {
        assert(sg.insert((r, t)).count(v) == sg.count(v));
        axiom_filter_count(sg.insert((r, t)), f, v);
        axiom_filter_count(sg, f, v);
    }

    assert forall|v: (int, T)|
        #[trigger] sg.filter(f).count(v) == 0 implies
            sg.insert((r, t)).filter(f).count(v) == 0
    by {
        axiom_filter_count(sg.insert((r, t)), f, v);
        axiom_filter_count(sg, f, v);
    }

    // Now prove the length equality
    // len(m) = sum of count(m, v) for all v
    // Let's compute both sides
    // LHS = sum of sg.insert((r,t)).filter(f).count(v) for all v
    //     = sum of (if f(v) then sg.insert((r,t)).count(v) else 0) for all v
    //     = sum of (if f(v) then (if v==(r,t) then count(sg,v)+1 else count(sg,v)) else 0) for all v
    //     = (sum of count(sg,v) for all v where f(v)) + 1
    // RHS = len(filter(sg, f)) + 1
    //     = (sum of count(sg,v) for all v where f(v)) + 1
    // So LHS = RHS

    // Since len is the sum of counts over all elements (including those with count 0),
    // and count is 0 for elements not in the dom:
    assert(Self::filter_r(sg.insert((r, t)), r).len() ==
        Self::filter_r(sg, r).len() + 1) by {
        // len(m) = sum of count(m, v) for all v
        // Let's compute both sides
        // LHS = sum of sg.insert((r,t)).filter(f).count(v) for all v
        //     = sum of (if f(v) then sg.insert((r,t)).count(v) else 0) for all v
        //     = sum of (if f(v) then (if v==(r,t) then count(sg,v)+1 else count(sg,v)) else 0) for all v
        //     = (sum of count(sg,v) for all v where f(v)) + 1
        // RHS = len(filter(sg, f)) + 1
        //     = (sum of count(sg,v) for all v where f(v)) + 1
        // So LHS = RHS
    }
