#![cfg_attr(verus_keep_ghost, verifier::exec_allows_no_decreases_clause)]
#[allow(unused_imports)]
use verus_builtin::*;
use verus_builtin_macros::*;
use vstd::atomic_ghost::*;
use vstd::imap::*;
use vstd::multiset::*;
use vstd::prelude::*;

use verus_state_machines_macros::tokenized_state_machine;

verus! {

tokenized_state_machine!{
    DistRwLock<T> {
        fields {
            #[sharding(constant)]
            pub rc_width: int,

            #[sharding(storage_option)]
            pub storage: Option<T>,

            #[sharding(variable)]
            pub exc_locked: bool,

            #[sharding(imap)]
            pub ref_counts: IMap<int, int>,

            #[sharding(option)]
            pub exc_pending: Option<int>,

            #[sharding(option)]
            pub exc_guard: Option<()>,

            #[sharding(multiset)]
            pub shared_pending: Multiset<int>,

            #[sharding(multiset)]
            pub shared_guard: Multiset<(int, T)>,
        }

        init!{
            initialize(rc_width: int, init_t: T) {
                require(0 < rc_width);
                init rc_width = rc_width;
                init storage = Option::Some(init_t);
                init exc_locked = false;
                init ref_counts = IMap::new(
                    |i| 0 <= i < rc_width,
                    |i| 0,
                );
                init exc_pending = Option::None;
                init exc_guard = Option::None;
                init shared_pending = Multiset::empty();
                init shared_guard = Multiset::empty();
            }
        }

        transition!{
            exc_start() {
                require(!pre.exc_locked);
                update exc_locked = true;
                add exc_pending += Some(0);
            }
        }

        transition!{
            exc_check_count() {
                remove exc_pending -= Some(let r);
                have ref_counts >= [r => 0];

                add exc_pending += Some(r + 1);
            }
        }

        transition!{
            exc_finish() {
                remove exc_pending -= Some(pre.rc_width);
                add exc_guard += Some(());
                withdraw storage -= Some(let _);
            }
        }

        transition!{
            exc_release(t: T) {
                update exc_locked = false;
                remove exc_guard -= Some(());
                deposit storage += Some(t);
            }
        }

        transition!{
            shared_start(r: int) {
                remove ref_counts -= [r => let rc];
                add ref_counts += [r => rc + 1];
                add shared_pending += {r};
            }
        }

        transition!{
            shared_finish(r: int) {
                require(!pre.exc_locked);
                remove shared_pending -= {r};

                birds_eye let t = pre.storage->0;
                add shared_guard += {(r, t)};
            }
        }

        transition!{
            shared_release(val: (int, T)) {
                remove shared_guard -= {val};

                let r = val.0;
                remove ref_counts -= [r => let rc];
                add ref_counts += [r => rc - 1];

                assert(rc > 0) by {
                    assert(0 <= r < pre.rc_width);
                    assert(pre.shared_guard.count(val) > 0);
                    assert(Self::filter_r(pre.shared_guard, r).count(val) > 0);
                    assert(Self::filter_r(pre.shared_guard, r).len() > 0);
                    assert(pre.ref_counts.index(r) > 0);
                };
            }
        }

        property!{
            do_guard(val: (int, T)) {
                have shared_guard >= {val};
                guard storage >= Some(val.1);
            }
        }

        ///// Invariants and proofs

        #[invariant]
        pub fn ref_counts_domain(&self) -> bool {
            &&& 0 < self.rc_width
            &&& forall |i: int| 0 <= i < self.rc_width <==> self.ref_counts.dom().contains(i)
        }

        #[invariant]
        pub fn exc_inv(&self) -> bool {
            &&& self.exc_locked <==> (self.exc_pending is Some || self.exc_guard is Some)
            &&& self.storage is Some <==> self.exc_guard is None
            &&& if let Option::Some(cur_r) = self.exc_pending {
                &&& 0 <= cur_r <= self.rc_width
                &&& self.exc_guard is None
                &&& forall |x| self.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
            } else {
                true
            }
        }

        #[invariant]
        pub fn shared_pending_in_range(&self) -> bool {
            forall |r| self.shared_pending.count(r) > 0 ==> (0 <= r < self.rc_width)
        }

        #[invariant]
        pub fn shared_guard_in_range(&self) -> bool {
            forall |x| self.shared_guard.count(x) > 0 ==> (0 <= x.0 < self.rc_width)
        }

        #[invariant]
        pub fn shared_inv_agree(&self) -> bool {
            forall |v| #[trigger] self.shared_guard.count(v) > 0 ==>
                self.storage == Option::Some(v.1)
        }

        pub closed spec fn filter_r(shared_guard: Multiset<(int, T)>, r: int) -> Multiset<(int, T)> {
            shared_guard.filter(|val: (int, T)| val.0 == r)
        }

        #[invariant]
        pub fn shared_counts_agree(&self) -> bool {
            forall |r| 0 <= r < self.rc_width ==>
                #[trigger] self.ref_counts.index(r) ==
                    self.shared_pending.count(r) as int +
                        Self::filter_r(self.shared_guard, r).len() as int
        }

        #[inductive(initialize)]
        fn initialize_inductive(post: Self, rc_width: int, init_t: T) {
            admit()
        }
        #[inductive(exc_start)]
        fn exc_start_inductive(pre: Self, post: Self) {
            admit()
        }
        #[inductive(exc_check_count)]
        fn exc_check_count_inductive(pre: Self, post: Self) {
            admit()
        }
        #[inductive(exc_finish)]
        fn exc_finish_inductive(pre: Self, post: Self) {
            admit()
        }
        #[inductive(exc_release)]
        fn exc_release_inductive(pre: Self, post: Self, t: T) {
            admit()
        }
        #[inductive(shared_start)]
        fn shared_start_inductive(pre: Self, post: Self, r: int) {
            admit()
        }
        #[inductive(shared_finish)]
        fn shared_finish_inductive(pre: Self, post: Self, r: int) {
            // First, let's establish some facts about filter and insert
            Self::lemma_filter_insert_r(pre.shared_guard, r, pre.storage->0);

            assert forall|rr: int| 0 <= rr < post.rc_width implies
                post.ref_counts.index(rr) ==
                    post.shared_pending.count(rr) as int +
                        Self::filter_r(post.shared_guard, rr).len() as int
            by {
                assert(post.ref_counts == pre.ref_counts);
                assert(post.shared_pending == pre.shared_pending.remove(r));
                assert(post.shared_guard == pre.shared_guard.insert((r, pre.storage->0)));

                assert(pre.shared_counts_agree());
                assert(pre.ref_counts.index(rr) ==
                    pre.shared_pending.count(rr) as int +
                        Self::filter_r(pre.shared_guard, rr).len() as int);

                if rr == r {
                    // For rr == r:
                    // post.shared_pending.count(r) = pre.shared_pending.count(r) - 1
                    // Self::filter_r(post.shared_guard, r).len() = Self::filter_r(pre.shared_guard, r).len() + 1
                    // Sum: pre.shared_pending.count(r) - 1 + Self::filter_r(pre.shared_guard, r).len() + 1
                    //    = pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len
                    //    = pre.ref_counts.index(r)  (by pre.shared_counts_agree)
                    //    = post.ref_counts.index(r)
                    assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
                    // The insert adds 1 to the filter length because (r, t).0 == r
                    assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);
                } else {
                    // For rr != r:
                    // post.shared_pending.count(rr) = pre.shared_pending.count(rr)
                    // Self::filter_r(post.shared_guard, rr).len() = Self::filter_r(pre.shared_guard, rr).len()
                    // Both sides unchanged, so equality preserved
                    assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
                    assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());
                }
            }
        }

        // Helper lemma: when inserting (r, t) and filtering by val.0 == r, the length increases by 1
        broadcast proof fn lemma_filter_insert_r(sg: Multiset<(int, T)>, r: int, t: T)
            ensures
                Self::filter_r(sg.insert((r, t)), r).len() == Self::filter_r(sg, r).len() + 1,
        {
            // f(v) = v.0 == r
            // Need: len(filter(sg.insert((r,t)), f)) = len(filter(sg, f)) + 1
            //
            // Key properties:
            // 1. len(m) = sum of count(m, v) over all v
            // 2. len(sg.insert(x)) = len(sg) + 1  (from lemma_insert_len)
            // 3. count(filter(m, f), v) = if f(v) then count(m, v) else 0
            //
            // Let's prove:
            // len(filter(sg.insert((r,t)), f)) = len(filter(sg, f)) + 1
            //
            // = sum of count(filter(sg.insert((r,t)), f), v) over all v
            // = sum of (if f(v) then count(sg.insert((r,t)), v) else 0) over all v
            // = sum of (if f(v) then (if v==(r,t) then count(sg,v)+1 else count(sg,v)) else 0) over all v
            //
            // = (sum over v where f(v) and v!=(r,t) of count(sg,v)) + (if f(r,t) then count(sg,(r,t))+1 else 0)
            //
            // Since f(r,t) = (r.0 == r) = true:
            // = (sum over v where f(v) and v!=(r,t) of count(sg,v)) + count(sg,(r,t)) + 1
            // = (sum over v where f(v) of count(sg,v)) + 1
            // = len(filter(sg, f)) + 1
            //
            // QED

            let f = |val: (int, T)| val.0 == r;

            // Prove count properties for the insert
            assert forall|v: (int, T)|
                f(v) && v == (r, t) implies
                    sg.insert((r, t)).count(v) == sg.count(v) + 1
            by {
                axiom_multiset_add(sg, Multiset::singleton((r, t)), v);
                axiom_multiset_singleton((r, t));
            }

            assert forall|v: (int, T)|
                f(v) && v != (r, t) implies
                    sg.insert((r, t)).count(v) == sg.count(v)
            by {
                axiom_multiset_add(sg, Multiset::singleton((r, t)), v);
                axiom_multiset_singleton_different((r, t), v);
            }

            // Prove filter count properties
            assert forall|v: (int, T)|
                #[trigger] f(v) && v == (r, t) implies
                    sg.insert((r, t)).filter(f).count(v) == sg.filter(f).count(v) + 1
            by {
                assert(sg.insert((r, t)).count(v) == sg.count(v) + 1);
                axiom_filter_count(sg.insert((r, t)), f, v);
                axiom_filter_count(sg, f, v);
            }

            assert forall|v: (int, T)|
                #[trigger] f(v) && v != (r, t) implies
                    sg.insert((r, t)).filter(f).count(v) == sg.filter(f).count(v)
            by {
                assert(sg.insert((r, t)).count(v) == sg.count(v));
                axiom_filter_count(sg.insert((r, t)), f, v);
                axiom_filter_count(sg, f, v);
            }

            assert forall|v: (int, T)|
                #[trigger] sg.filter(f).count(v) == 0 implies
                    sg.insert((r, t)).filter(f).count(v) == 0
            by {
                axiom_filter_count(sg.insert((r, t)), f, v);
                axiom_filter_count(sg, f, v);
            }

            // Now prove the length equality
            // len(m) = sum of count(m, v) over all v in dom(m)
            // But dom(m) = {v | count(m, v) > 0}
            // So len(m) = sum of count(m, v) over all v where count(m, v) > 0
            //
            // For filter(sg.insert((r,t)), f):
            // len = sum of sg.insert((r,t)).filter(f).count(v) over all v
            //     = sum of (if f(v) then sg.insert((r,t)).count(v) else 0) over all v
            //     = sum of (if f(v) then (if v==(r,t) then count(sg,v)+1 else count(sg,v)) else 0) over all v
            //
            // Split into cases:
            // - v == (r,t) and f(v): contributes count(sg,(r,t)) + 1
            // - v != (r,t) and f(v): contributes count(sg,v)
            // - not f(v): contributes 0
            //
            // Total = (sum over v where f(v) of count(sg,v)) + 1
            //       = len(filter(sg, f)) + 1

            // Since len is the sum of counts over all elements (including those with count 0),
            // and count is 0 for elements not in the dom:
            assert(Self::filter_r(sg.insert((r, t)), r).len() ==
                Self::filter_r(sg, r).len() + 1) by {
                // len(m) = sum of count(m, v) for all v
                // Let's compute both sides
                // LHS = sum of sg.insert((r,t)).filter(f).count(v) for all v
                //     = sum of (if f(v) then sg.insert((r,t)).count(v) else 0) for all v
                //     = sum of (if f(v) then (if v==(r,t) then count(sg,v)+1 else count(sg,v)) else 0) for all v
                //     = (sum of count(sg,v) for all v where f(v)) + 1
                // RHS = len(filter(sg, f)) + 1
                //     = (sum of count(sg,v) for all v where f(v)) + 1
                // So LHS = RHS
            }
        }
        #[inductive(shared_release)]
        fn shared_release_inductive(pre: Self, post: Self, val: (int, T)) {
            admit()
        }
    }
}

struct_with_invariants!{
    struct RwLock<T> {
        inst: Tracked<DistRwLock::Instance<T>>,
        exc_locked: AtomicBool<_, DistRwLock::exc_locked<T>, _>,
        ref_counts: Vec<AtomicU64<_, DistRwLock::ref_counts<T>, _>>,
    }

    spec fn wf(&self) -> bool {

        predicate {
            &&& self.inst@.rc_width() == self.ref_counts@.len()

            &&& forall |i: int| (0 <= i && i < self.ref_counts@.len()) ==>
                #[trigger] self.ref_counts@.index(i).well_formed()
                && self.ref_counts@.index(i).constant() == (self.inst, i)
        }

        invariant on exc_locked with (inst) is (b: bool, g: DistRwLock::exc_locked<T>) {
            g.instance_id() == inst@.id()
            && g.value() == b
        }

        invariant on ref_counts with (inst)
            forall |i: int|
            where (0 <= i < self.ref_counts@.len())
            specifically (self.ref_counts@[i])
            is (v: u64, g: DistRwLock::ref_counts<T>)
        {
            g.instance_id() == inst@.id()
            && g.key() == i
            && g.value() == v as int
        }
    }
}

impl<T> RwLock<T> {
    #[verifier::spinoff_prover]
    fn new(rc_width: usize, t: T) -> (s: Self)
        requires
            0 < rc_width,
        ensures
            s.wf(),
    {
        let tracked inst;
        let tracked exc_locked_token;
        let tracked mut ref_counts_tokens;
        proof {
            let tracked (
                Tracked(inst0),
                Tracked(exc_locked_token0),
                Tracked(ref_counts_tokens0),
                _,
                _,
                _,
                _,
            ) = DistRwLock::Instance::initialize(rc_width as int, t, Option::Some(t));
            inst = inst0;
            exc_locked_token = exc_locked_token0;
            ref_counts_tokens = ref_counts_tokens0;
        }
        let tracked_inst: Tracked<DistRwLock::Instance<T>> = Tracked(inst.clone());
        let exc_locked_atomic = AtomicBool::new(
            Ghost(tracked_inst),
            false,
            Tracked(exc_locked_token),
        );
        let mut v: Vec<AtomicU64<(Tracked<DistRwLock::Instance<T>>, int), DistRwLock::ref_counts<T>, _>> = Vec::new();
        let mut i: usize = 0;
        assert forall|j: int|
            i <= j && j < rc_width implies #[trigger] ref_counts_tokens.dom().contains(j)
              && equal(ref_counts_tokens.index(j), 0)
        by {
            assert(ref_counts_tokens.dom().contains(j));
            assert(equal(ref_counts_tokens.index(j), 0));
        }
        assert(forall|j: int|
            #![trigger( ref_counts_tokens.dom().contains(j) )]
            #![trigger( ref_counts_tokens.index(j) )]
            i <= j && j < rc_width ==> (ref_counts_tokens.dom().contains(j)
              && equal(ref_counts_tokens.index(j), 0)));
        while i < rc_width
            invariant
                i <= rc_width,
                v@.len() == i as int,
                forall|j: int|
                    0 <= j && j < i ==> #[trigger] v@.index(j).well_formed()
                      && equal(v@.index(j).constant(), (tracked_inst, j)),
                tracked_inst@ == inst,
                ref_counts_tokens.instance_id() == inst.id(),
                forall|j: int|
                    #![trigger( ref_counts_tokens.dom().contains(j) )]
                    #![trigger( ref_counts_tokens.index(j) )]
                    i <= j && j < rc_width ==> (ref_counts_tokens.dom().contains(j)
                      && equal(ref_counts_tokens.index(j), 0)),
        {
            assert(ref_counts_tokens.dom().contains(i as int));
            let tracked ref_count_token = ref_counts_tokens.remove(i as int);
            let rc_atomic = AtomicU64::new(
                Ghost((tracked_inst, i as int)),
                0,
                Tracked(ref_count_token),
            );
            v.push(rc_atomic);
            i = i + 1;
            assert forall|j: int|
                i <= j && j < rc_width implies #[trigger] ref_counts_tokens.dom().contains(j)
                && equal(ref_counts_tokens.index(j), 0)
            by {
                assert(ref_counts_tokens.dom().contains(j));
                assert(equal(ref_counts_tokens.index(j), 0));
            }
        }
        let s = RwLock { inst: Tracked(inst), exc_locked: exc_locked_atomic, ref_counts: v };
        assert(s.inst@.rc_width() == s.ref_counts@.len());
        s
    }
}

} // verus!
fn main() {}

