            // post.shared_guard = pre.shared_guard.remove((r,t))
            // filter_r(post.shared_guard, r) removes (r,t) from the filter
            // So filter_r(post.shared_guard, r).len = filter_r(pre.shared_guard, r).len - 1

            assert(post.ref_counts.index(rr) == pre.ref_counts.index(rr) - 1);

            let f = |val: (int, T)| val.0 == rr;
            let x = (r, t);

            // Prove: filter_r(pre.shared_guard.remove(x), r).len = filter_r(pre.shared_guard, r).len - 1
            // Since f(x) = true (because x.0 = r), removing x from pre.shared_guard
            // decreases the filter length by 1

            // filter(sg.remove(x), f) = filter(sg, f).remove(x) when f(x)
            // So len(filter(sg.remove(x), f)) = len(filter(sg, f).remove(x))
            //                            = len(filter(sg, f)) - 1  (if x is in the filter)

